import type { Ref } from 'vue'
import { createVNode, getCurrentInstance, inject, provide, ref, render } from 'vue'
import { RebornToast } from '#components'
import { type ToastOptions, defaultOptions, getToastOptionKey, globalOptionRef } from './reborn-toast.config'

let toastContainer: HTMLElement | null = null
let globalTimer: ReturnType<typeof setTimeout> | null = null
let isMounted = false

/**
 * 确保 toast 容器已挂载到 DOM（命令式调用时自动初始化）
 */
function mountToastContainer() {
  if (typeof document === 'undefined' || isMounted) return

  toastContainer = document.createElement('div')
  document.body.appendChild(toastContainer)

  const vnode = createVNode(RebornToast)
  const instance = getCurrentInstance()
  if (instance) {
    vnode.appContext = instance.appContext
  }
  // 注入全局状态（作为兜底，即便没有 appContext，RebornToast 内部也会从 config 导入）
  if (vnode.appContext) {
    vnode.appContext.provides[getToastOptionKey()] = globalOptionRef
  }
  render(vnode, toastContainer)
  isMounted = true
}

/**
 * 统一的状态更新与计时器管理
 */
function applyOptions(targetRef: Ref<ToastOptions>, options: ToastOptions) {
  // 合并默认配置、传入配置，并强制显示
  const finalOptions = { ...defaultOptions, ...options, show: true }

  // 处理 duration 为空的情况
  if (finalOptions.duration === undefined || finalOptions.duration === null) {
    finalOptions.duration = defaultOptions.duration
  }

  targetRef.value = finalOptions

  // 处理计时器
  if (globalTimer) clearTimeout(globalTimer)
  if (targetRef.value.duration! > 0) {
    globalTimer = setTimeout(() => {
      targetRef.value.show = false
    }, targetRef.value.duration)
  }
}

/**
 * 显示 toast（全局单例）
 */
function invoke(options: ToastOptions) {
  mountToastContainer()
  applyOptions(globalOptionRef, options)
}

/**
 * 规范化参数，支持 (msg: string, ...) 和 (options: ToastOptions, ...)
 */
function normalizeOptions(msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>, defaultDuration = 2000): ToastOptions {
  if (typeof msg === 'string') {
    return { msg, duration: duration ?? defaultDuration, ...opts }
  }
  return { ...msg, ...opts }
}

/**
 * 命令式 Toast API，类似 Element Plus 的 ElMessage
 */
export const showToast = {
  show: invoke,
  hide: () => { globalOptionRef.value.show = false },
  success: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
    invoke({ color: 'success', iconName: 'success', ...normalizeOptions(msg, duration, opts, 1500) }),
  error: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
    invoke({ color: 'error', iconName: 'error', ...normalizeOptions(msg, duration, opts, 2000) }),
  warning: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
    invoke({ color: 'warning', iconName: 'warning', ...normalizeOptions(msg, duration, opts, 2000) }),
  info: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
    invoke({ color: 'info', iconName: 'info', ...normalizeOptions(msg, duration, opts, 2000) }),
  loading: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
    invoke({ cover: false, iconName: 'loading', ...normalizeOptions(msg, duration, opts, duration ?? 0) }),
}

/**
 * Composable 式 Toast API，支持多实例（通过 selector 区分）
 */
export function useToast(selector = '') {
  const key = getToastOptionKey(selector)
  const instance = getCurrentInstance()

  // 如果是默认 selector，复用全局单例
  if (!selector) {
    mountToastContainer()
    const optionRef = inject<Ref<ToastOptions>>(key, globalOptionRef)
    if (instance) {
      provide(key, optionRef)
    }

    return {
      show: (options: ToastOptions) => { invoke(options) },
      hide: () => { globalOptionRef.value.show = false },
      close: () => { globalOptionRef.value.show = false },
      success: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
        invoke({ color: 'success', iconName: 'success', ...normalizeOptions(msg, duration, opts, 1500) }),
      error: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
        invoke({ color: 'error', iconName: 'error', ...normalizeOptions(msg, duration, opts, 2000) }),
      warning: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
        invoke({ color: 'warning', iconName: 'warning', ...normalizeOptions(msg, duration, opts, 2000) }),
      info: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
        invoke({ color: 'info', iconName: 'info', ...normalizeOptions(msg, duration, opts, 2000) }),
      loading: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
        invoke({ cover: false, iconName: 'loading', ...normalizeOptions(msg, duration, opts, duration ?? 0) }),
    }
  }

  // selector 非空时：独立 optionRef，支持多 toast 实例共存
  const optionRef = inject<Ref<ToastOptions>>(key, ref<ToastOptions>({ ...defaultOptions }))

  if (typeof document !== 'undefined' && !toastContainer) {
    toastContainer = document.createElement('div')
    document.body.appendChild(toastContainer)

    const vnode = createVNode(RebornToast)
    if (instance) {
      vnode.appContext = instance.appContext
    }
    if (vnode.appContext) {
      vnode.appContext.provides[key] = optionRef
    }
    render(vnode, toastContainer)
  }

  provide(key, optionRef)

  const show = (options: ToastOptions) => {
    applyOptions(optionRef, options)
  }

  return {
    show,
    hide: () => { optionRef.value.show = false },
    close: () => { optionRef.value.show = false },
    success: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
      show({ color: 'success', iconName: 'success', ...normalizeOptions(msg, duration, opts, 1500) }),
    error: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
      show({ color: 'error', iconName: 'error', ...normalizeOptions(msg, duration, opts, 2000) }),
    warning: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
      show({ color: 'warning', iconName: 'warning', ...normalizeOptions(msg, duration, opts, 2000) }),
    info: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
      show({ color: 'info', iconName: 'info', ...normalizeOptions(msg, duration, opts, 2000) }),
    loading: (msg: string | ToastOptions, duration?: number, opts?: Partial<ToastOptions>) =>
      show({ cover: false, iconName: 'loading', ...normalizeOptions(msg, duration, opts, duration ?? 0) }),
  }
}

import { ref } from 'vue';

export interface ToastOptions {
  msg?: string;
  duration?: number;
  iconName?: 'success' | 'error' | 'warning' | 'loading' | 'info';
  position?: 'top' | 'middle-top' | 'middle' | 'bottom';
  show?: boolean;
  zIndex?: number;
  cover?: boolean;
  color?: 'primary' | 'secondary' | 'success' | 'info' | 'warning' | 'error' | 'neutral' | '';
  direction?: 'horizontal' | 'vertical';
}

export const toastDefaultOptionKey = '__REBORN_TOAST_OPTION__';
export const defaultOptions: ToastOptions = { duration: 2000, show: false };
export const getToastOptionKey = (selector = '') => (selector ? `${toastDefaultOptionKey}${selector}` : toastDefaultOptionKey);

/**
 * 全局单例状态，放这里是为了避免 index.ts 和 RebornToast.vue 循环引用
 */
export const globalOptionRef = ref<ToastOptions>({ ...defaultOptions });

export const toastTheme = {
  root: 'inline-flex max-w-[70%] items-center justify-center rounded-xl bg-black/80 px-4 py-3 text-white shadow-lg transition-all duration-300',
  positions: { top: '-translate-y-[40vh]', 'middle-top': '-translate-y-[18vh]', middle: '', bottom: 'translate-y-[40vh]' },
  colors: {
    primary: 'bg-white border border-primary/20 text-primary shadow-sm dark:bg-gray-900',
    secondary: 'bg-white border border-secondary/20 text-secondary shadow-sm dark:bg-gray-900',
    success: 'bg-white border border-success/20 text-success shadow-sm dark:bg-gray-900',
    info: 'bg-white border border-info/20 text-info shadow-sm dark:bg-gray-900',
    warning: 'bg-white border border-warning/20 text-warning shadow-sm dark:bg-gray-900',
    error: 'bg-white border border-error/20 text-error shadow-sm dark:bg-gray-900',
    neutral: 'bg-white border border-neutral/20 text-neutral shadow-sm dark:bg-gray-900',
  },
  msg: 'text-sm break-all text-center',
};

import { inject, provide, ref, render, createVNode, getCurrentInstance } from 'vue'
import { deepMerge } from '@/lib/util'

export type ToastIconType = 'success' | 'error' | 'warning' | 'loading' | 'info'
export type ToastPositionType = 'top' | 'middle-top' | 'middle' | 'bottom'
export type ToastDirection = 'vertical' | 'horizontal'
export type ToastLoadingType = 'outline' | 'ring' | 'spinner' | 'bars-scale' | 'blocks-shuffle' | 'blocks-wave' | 'gooey-balls'

export type ToastColorType = 'primary' | 'secondary' | 'success' | 'info' | 'warning' | 'error' | 'neutral'

export type ToastOptions = {
    msg?: string
    duration?: number
    direction?: ToastDirection
    iconName?: ToastIconType
    iconSize?: number
    loadingType?: ToastLoadingType
    loadingColor?: string
    loadingSize?: number
    position?: ToastPositionType
    show?: boolean
    zIndex?: number
    cover?: boolean
    iconClass?: string
    classPrefix?: string
    color?: ToastColorType
    opened?: () => void
    closed?: () => void
}

const toastDefaultOptionKey = '__REBORN_TOAST_OPTION__'
export const defaultOptions: ToastOptions = { duration: 2000, show: false }

export function getToastOptionKey(selector: string) {
    return selector ? `${toastDefaultOptionKey}${selector}` : toastDefaultOptionKey
}

import RebornToast from './RebornToast.vue'

// 全局唯一的组件挂载节点与实例状态
let toastContainer: HTMLElement | null = null
let globalTimer: ReturnType<typeof setTimeout> | null = null

// 全局唯一的配置，保证应用中同一时刻只有一个 Toast 实际在工作
export const globalOptionRef = ref<ToastOptions>({ ...defaultOptions })

export function useToast(selector = '') {
    const key = getToastOptionKey(selector)
    const instance = getCurrentInstance()

    // 尝试在当前上下文中挂载或获取，以兼容不同端
    let optionRef = inject(key, globalOptionRef)

    // #ifdef H5
    if (!toastContainer) {
        toastContainer = document.createElement('view')
        toastContainer.id = 'reborn-toast-container'
        document.body.appendChild(toastContainer)

        const vnode = createVNode(RebornToast)

        // 桥接当前上下文，以支持 router, pinia 等
        if (instance) {
            vnode.appContext = instance.appContext
        } else if (!vnode.appContext) {
            vnode.appContext = { provides: {} } as any
        }

        // 极重要：在这里 provide key 使得动态渲染的 RebornToast 能 inject 到这个 Ref
        if (vnode.appContext) {
            if (!vnode.appContext.provides) vnode.appContext.provides = {}
            vnode.appContext.provides[key] = optionRef
        }

        render(vnode, toastContainer)
    }
    // #endif

    // 向下提供引用给可能写在页面里的 <RebornToast />，保证内外使用的 optionRef 永远映射到同一个实例
    provide(key, optionRef)

    const close = () => {
        if (globalTimer) {
            clearTimeout(globalTimer)
            globalTimer = null
        }
        optionRef.value = { ...optionRef.value, show: false }
    }

    const show = (option: ToastOptions | string) => {
        const next = deepMerge(defaultOptions, typeof option === 'string' ? { msg: option } : option)

        // 保证每次 show 时都是立刻覆盖当前唯一的提示
        optionRef.value = deepMerge(next, { show: true })

        if (globalTimer) {
            clearTimeout(globalTimer)
            globalTimer = null
        }

        if (next.duration !== undefined && next.duration > 0) {
            globalTimer = setTimeout(close, next.duration)
        }
    }

    const build = (base: ToastOptions) => (options: ToastOptions | string) => show(deepMerge(base, typeof options === 'string' ? { msg: options } : options))
    return {
        show,
        close,
        loading: build({ iconName: 'loading', duration: 0, cover: true }),
        success: build({ iconName: 'success', duration: 1500 }),
        error: build({ iconName: 'error' }),
        warning: build({ iconName: 'warning' }),
        info: build({ iconName: 'info' }),
    }
}

